sys_script_include.script:
var BasesItils = Class.create();
BasesItils.prototype = {
    initialize: function() {},

    rqBases: function() {

        var show = [];

        var currentUser = gs.getUserID(); // ID do usuário atual

        // Verificar se o usuário já tem uma inscrição pendente ou aprovada
        var grLinkRequester = new GlideRecord("x_1593182_bases_link_request");
        grLinkRequester.addEncodedQuery("assigned_to=" + currentUser + "^stateIN1,2"); // Verifica se o estado é Pendentes (1) ou Aprovadas (2)
        grLinkRequester.query();

        if (grLinkRequester.next()) {
            show = "Vazio"; // Se o usuário tem uma inscrição pendente ou aprovada, não mostra novas bases
        } else {
            var baseList = [];
            var grBases = new GlideRecord("x_1593182_bases_base");
            grBases.query();
            while (grBases.next()) {
                baseList.push(grBases.getUniqueValue());
            }

            if (baseList.length > 0) {
                show = "sys_idIN" + baseList.join(","); // Formata o retorno corretamente para Reference Qualifier
            } else {
                show = "Vazio";
            }
        }

        return show;
    },

    type: 'BasesItils'
};
